from author_common import *

def mc(doc,page,prompt,correct,b,c,e,why):
    add(doc,page,'single_choice',prompt,'a',why,[correct,b,c,e])
    q=qs[-1];q['id']=f'{doc}-x{sum(x["topic"]==doc for x in qs):02}';q['author_id']='question-engineer-b'

d='p2-t2-d04'
mc(d,8,'Đổi embedding model cho một corpus đã lập chỉ mục đòi hỏi kế hoạch nào?','Re-index corpus bằng model mới','Chỉ đổi tên collection','Giữ nguyên vector cũ và embed query mới tùy ý','Chỉ tăng top-k mà không đổi index','Vector từ các model khác nhau không bảo đảm cùng không gian; đổi model cần re-index toàn bộ.')
mc(d,9,'Một embedding model đứng đầu benchmark đa ngữ nhưng hệ thống phục vụ miền hẹp tiếng Việt. Bằng chứng nào nên quyết định lựa chọn cuối?','Kết quả trên golden set của miền ứng dụng','Chỉ số lượng tham số','Chỉ nhãn fine-tuned Vietnamese','Chỉ thứ hạng benchmark tiếng Anh','Benchmark rộng không đại diện đầy đủ miền hẹp; golden set của ứng dụng là trọng tài cuối cùng.')
mc(d,14,'Corpus rất lớn, ít query và chấp nhận latency cao hơn nên cân nhắc tầng lưu trữ nào?','Object storage','RAM cho mọi vector bất kể chi phí','Chỉ giữ vector trong context LLM','Không cần lưu chỉ mục','Object storage có chi phí thấp nhất nhưng latency cao hơn, QPS thấp hơn; thích hợp corpus lớn ít truy vấn.')
mc(d,18,'Vì sao RRF phù hợp ghép kết quả BM25 với vector search?','Dùng thứ hạng nên không cần normalize raw score giữa hai hệ','Buộc hai hệ có cùng thang cosine','Chỉ chọn kết quả BM25 và bỏ vector','Đòi mọi document có score bằng nhau','RRF là rank-only, tránh phải chuẩn hóa thang điểm BM25 và cosine khác nhau.')
mc(d,19,'ANN trả top-100 rồi filter chỉ giữ 2% corpus. Rủi ro chính là gì?','Còn rất ít kết quả và recall giảm âm thầm','Độ chính xác tự động đạt 100%','Filter tự mở rộng index vô hạn','Không cần test filter chọn lọc nữa','Post-filter có thể chỉ còn hai kết quả; filter càng chặt càng dễ làm recall sụp mà không báo lỗi.')
mc(d,20,'Một hệ retrieval giữ nhiều vector theo token/patch thay vì một vector mỗi document. Đánh đổi chính là gì?','Giữ chi tiết hơn nhưng tốn dung lượng và cần hỗ trợ multi-vector','Chắc chắn dùng ít dung lượng hơn single-vector','Không còn cần similarity scoring','Chỉ hoạt động với văn bản không có bảng','Late interaction giữ chi tiết token/patch với MaxSim nhưng tăng storage và yêu cầu DB hỗ trợ multi-vector.')
mc(d,22,'Hierarchical chunking tổ chức truy xuất thế nào?','Retrieve child nhỏ rồi trả parent rộng hơn','Chỉ cắt byte cố định và bỏ ranh giới câu','Chỉ embed toàn corpus thành một vector','Chỉ giữ tiêu đề mà bỏ nội dung','Parent là page, child là paragraph; retrieve child và return parent giúp giữ ngữ cảnh.')
mc(d,24,'Trong two-stage retrieval, cross-encoder đóng vai trò nào?','Chấm relevance từng cặp query-document sau bước lấy candidate','Embed query và document hoàn toàn riêng để lấy candidate nhanh','Chỉ nén index trên disk','Chỉ đặt TTL cho cache','Bi-encoder lấy candidate nhanh ở stage 1; cross-encoder xét chung query/doc để tăng precision ở stage 2.')
mc(d,26,'Câu hỏi yêu cầu lần theo quan hệ nhiều thực thể qua nhiều tài liệu phù hợp bổ sung cấu trúc nào?','Knowledge graph và traversal nhiều hop','Chỉ tăng chunk overlap đến toàn corpus','Chỉ dùng exact string match','Loại bỏ mọi entity ID','GraphRAG biểu diễn entity-relation và hỗ trợ câu trả lời là quan hệ nhiều hop, khác tìm đoạn văn tương tự.')
mc(d,28,'Agentic retrieval khác classic RAG ở quyết định nào?','Chọn nguồn, tách câu hỏi và truy xuất nhiều vòng khi thiếu bằng chứng','Luôn đúng một lần top-k cho mọi query','Không dùng tool truy xuất','Không phát sinh thêm latency hoặc token','Agentic retrieval lập kế hoạch và phản tỉnh bằng chứng, có thể lặp qua nhiều nguồn với chi phí LLM call/latency thêm.')
mc(d,30,'Retrieval tool nên trả gì ngoài text để câu trả lời có thể truy nguồn?','Citation và score','Chỉ một câu khẳng định không có URL','Chỉ tên model generation','Chỉ token count của system prompt','Citation và score giúp truy nguồn; description rõ, filter enum và top-k có trần giúp agent dùng tool đúng.')
mc(d,32,'Semantic cache thiếu namespace tenant gây loại lỗi nào?','Rò câu trả lời chứa dữ liệu sang tenant khác','Chỉ làm cache miss nhiều hơn','Chỉ giảm tốc encode','Tự bảo đảm ẩn danh vì dùng vector','Không cô lập namespace có thể trả dữ liệu user/tenant khác; đây là lỗ hổng bảo mật.')
mc(d,33,'Agent tuân theo lệnh nằm trong đoạn tài liệu được retrieve. Cách sửa phù hợp là gì?','Tách dữ liệu khỏi instruction và không cho retrieved text điều khiển tool','Nâng top-k để thêm nhiều lệnh hơn','Lưu vĩnh viễn đoạn đó vào semantic cache','Ẩn citation để agent không đọc nguồn','Retrieved text là dữ liệu; prompt injection qua tài liệu không được trở thành quyền điều khiển tool.')
mc(d,35,'Trong FeatureView, timestamp_field hỗ trợ yêu cầu quan trọng nào?','Point-in-time join để tránh dùng dữ liệu tương lai','Tự động chọn mọi GPU instance','Thay entities làm khóa lookup','Vô hiệu hóa toàn bộ TTL','Timestamp_field xác định thời gian feature cho PIT join, thiếu nó có thể làm leakage.')
mc(d,36,'Amount của giao dịch chỉ có khi request đến, còn avg_amount_7d đã lưu. Cách tạo amount/avg phù hợp là gì?','On-demand feature kết hợp request với feature lưu sẵn','Precompute mọi amount tương lai','Dùng nhãn tương lai thay amount hiện tại','Chỉ lấy latest amount của một user khác','On-demand ghép stored feature với request data và dùng cùng công thức cho training/serving.')
mc(d,42,'Training parse giờ UTC nhưng serving parse local timezone có thể gây vấn đề nào?','Training-serving skew ở feature giờ trong ngày','Chỉ làm tăng số vector dimension','Tự cải thiện fairness','Không ảnh hưởng vì cùng là datetime','Hai cách parse khác nhau tạo giá trị feature khác nhau dù model không đổi; cần định nghĩa thống nhất.')
mc(d,54,'Vì sao chunk code theo ranh giới AST có thể tốt hơn cắt theo số ký tự?','Giữ nguyên hàm/class cùng scope, imports và signature','Loại bỏ hoàn toàn dependency giữa hàm','Bảo đảm mọi hàm dài bằng nhau','Cho phép bỏ hết metadata file/dòng','Nghĩa code nằm ở khối cú pháp; cắt giữa hàm làm mất signature, imports, scope và tạo mảnh vô nghĩa.')

d='p2-t2-d05'
mc(d,7,'Continuous batching giải quyết hạn chế nào của static batching khi request có độ dài khác nhau?','Cho request vào/ra trong lúc generation thay vì chờ cả batch','Buộc mọi output có cùng độ dài','Chỉ phục vụ một request đến khi hết queue','Loại bỏ hoàn toàn KV cache','Static batching để request dài chặn queue; continuous batching cho request tham gia/rời ở từng bước.')
mc(d,9,'Inference CPU-only trên laptop nên cân nhắc định dạng nào?','GGUF Q4_K_M','NVFP4 chỉ dành Blackwell cho mọi CPU','Chỉ BF16 không xét RAM','NF4 chỉ vì tên có 4-bit dù mục tiêu là fine-tuning','GGUF Q4_K_M được khuyến nghị cho CPU-only/edge; NF4 gắn với QLoRA fine-tune.')
mc(d,10,'PagedAttention giảm lãng phí KV cache bằng nguyên lý nào?','Ánh xạ các page không cần liên tiếp vật lý','Đặt một contiguous block lớn cố định cho mọi request','Xóa KV cache ở mọi token','Chỉ giảm số user được phép gọi','KV cache được tổ chức như virtual memory pages, cho cấp phát động thay contiguous blocks gây fragmentation.')
mc(d,11,'MLA giúp context dài hơn trên cùng VRAM bằng cách nào?','Nén biểu diễn attention xuống latent nhỏ để giảm KV memory','Nhân bản toàn bộ KV cache nhiều lần','Tăng mọi weight lên FP32','Tắt mọi attention computation','MLA nén xuống latent vector, giảm KV memory so với standard MHA.')
mc(d,13,'FlashAttention giảm traffic bộ nhớ nhờ cách xử lý nào?','Tile Q/K/V trong SRAM và online softmax','Ghi đầy đủ ma trận attention ra HBM ở mọi bước','Tăng số lần đọc ghi HBM cho mỗi softmax','Chuyển mọi phép attention thành network call','Tiling và online softmax tránh nhiều vòng đọc/ghi HBM của attention thông thường.')
mc(d,14,'CUDA Graph replay nhắm giảm overhead nào trong decode?','Lặp lại Python/launch overhead cho chuỗi GPU command tương tự','Chi phí lưu toàn bộ corpus RAG','Độ dài của văn bản đầu vào','Số layer trong model weights','Decode lặp cùng ops theo token; capture/replay command stream bỏ overhead mỗi bước.')
mc(d,15,'Một đội cần runtime local CPU/edge và GPU offload hỗn hợp. Engine nào phù hợp?','llama.cpp','Dynamo chỉ như GPU P/D orchestrator','Istio chỉ như service mesh','MLflow Registry thay inference engine','llama.cpp hỗ trợ GGUF native, CPU+GPU mixed offload và Apple Metal cho local/edge.')
mc(d,18,'Prefix-cache hit giúp giảm phần công việc nào khi system prompt lặp lại?','Prefill của prefix chung','Mọi token decode trong mọi câu trả lời mới','Toàn bộ chi phí training model','Tất cả request queue bất kể tải','RadixAttention/APC tái sử dụng KV của shared prefix nên có thể skip prefill phần đó.')
mc(d,20,'Structured generation dùng JSON Schema hoặc grammar nhằm kiểm soát phần nào?','Hình thức output theo ràng buộc định dạng','Bảo đảm mọi fact sinh ra đều đúng','Thay thế toàn bộ kiểm tra dữ liệu nguồn','Tự cấp quyền gọi mọi tool','Grammar-constrained output ép định dạng; parser có thể tách reasoning_content và content nhưng không tự chứng minh factuality.')
mc(d,21,'Serving bị OOM trong prefill dài. Knob nào trực tiếp liên quan để giảm kích thước công việc prefill?','Giảm chunked-prefill-size','Tăng burst concurrent requests không giới hạn','Tắt metrics để tránh GPU dùng RAM','Đổi tên endpoint /health','Production tuning nêu giảm chunked-prefill-size khi prefill OOM; cap running requests nhắm burst/decode OOM.')
mc(d,22,'Tách prefill/decode thành hai pool đặc biệt đáng cân nhắc cho workload nào?','Long-context RAG có prefill nặng','Chỉ prompt ngắn độc nhất không reuse','Bất kỳ request đơn giản nào cũng miễn transfer cost','Chỉ classifier không sinh token','Disaggregation giảm tranh chấp prefill/decode nhưng có KV transfer overhead; rõ lợi ích với prefill-heavy RAG.')
mc(d,23,'Multi-LoRA serving tiết kiệm tài nguyên bằng kiến trúc nào?','Một base model dùng nhiều domain adapter theo request','Mỗi adapter luôn mang toàn bộ base model riêng','Bỏ base model chỉ chạy adapter rỗng','Ghép mọi adapter thành một prompt text','Một base model cùng nhiều LoRA adapter giảm VRAM và chi phí so với nhiều deployment độc lập.')
mc(d,26,'Tensor Parallelism chủ yếu chia gì giữa GPU?','Weights trong từng layer','Chỉ các request độc lập','Chỉ tập layer liên tiếp thành stage','Chỉ các domain adapter theo tenant','TP chia weights/layer và cần all-reduce; PP chia layer, DP chia requests, EP chia experts.')
mc(d,29,'Embedding/reranker serving khác autoregressive generation ở đặc điểm nào?','Một forward pass, không có decode loop','Luôn cần KV cache tăng theo từng output token','Luôn phải dùng continuous batching giống decode','Không thể batch theo độ dài token','Embedding/reranker là prefill-bound, một forward pass; large static token-sorted batch là hướng throughput phù hợp.')
mc(d,30,'Semantic cache khác prefix/KV cache ở điều gì?','Có thể trả response cũ cho câu hỏi gần nghĩa','Chỉ skip prefill cho exact prefix chung','Chỉ cache GPU command stream','Không có nguy cơ stale answer','Semantic cache dựa meaning và similarity; prefix cache tái sử dụng KV chung, semantic hit có thể tránh inference nhưng có collision/staleness.')
mc(d,31,'Pre-generation routing khác cascade ở thời điểm quyết định model như thế nào?','Chọn model trước khi sinh thay vì sinh bằng model rẻ rồi mới defer','Luôn gọi cả model rẻ và mạnh trước mọi request','Chỉ đổi GPU sau khi câu trả lời hoàn tất','Bắt buộc mọi request vào frontier model','Routing classifier chọn trước generation; cascade đã trả chi phí sinh model rẻ trước khi defer.')
mc(d,39,'Khi endpoint quá tải, graceful degradation có thể thực hiện thế nào?','Trả cached/shorter response hoặc route sang model nhỏ hơn','Chỉ tăng timeout vô hạn','Tiếp tục nhận traffic dù circuit breaker mở','Tắt mọi health check để tránh báo lỗi','SLA best practices nêu circuit breaker/fallback và cached, shorter response, smaller model để giảm tải.')

d='p2-t2-d06'
mc(d,7,'Thành phần MLflow nào chuẩn hóa packaging model cho nhiều nền tảng deploy?','Models','Tracking chỉ như kho metrics','Registry chỉ như stage lifecycle','Projects chỉ như mô tả run environment','Models cung cấp format packaging như sklearn, pytorch, pyfunc để triển khai trên nhiều nền tảng.')
mc(d,8,'Confusion matrix nên được lưu trong nhóm thông tin nào của experiment?','Artifacts','Hyperparameter bất biến','Stage Production','Entity online key','Artifacts gồm plots, confusion matrix và config file lưu cùng run để trace back.')
mc(d,9,'So sánh accuracy với latency giữa các run giúp giải quyết câu hỏi nào?','Đánh đổi chất lượng và tốc độ của các cấu hình','Chỉ số byte của file pointer','GPU nào thuộc namespace nào','Có nên xóa toàn bộ lịch sử dataset','Scatter plot accuracy vs latency hỗ trợ so sánh run; param diff giúp debug regression.')
mc(d,10,'Alias champion và challenger hỗ trợ cách quản lý model nào?','Giữ production cùng candidate A/B trong registry','Xóa version production trước khi test candidate','Thay hash dataset bằng tên tùy ý','Buộc chỉ một version được tồn tại','Registry cho nhiều version cùng tồn tại, champion đại diện production và challenger candidate A/B.')
mc(d,11,'Khi incident xảy ra, bộ tag nào giúp lần ngược model về dữ liệu và code?','data_version, git_commit và eval_accuracy','Chỉ tên màu giao diện','Chỉ timezone người dùng cuối','Chỉ số cổng endpoint','Các tag data version, git commit, eval metric được khuyến nghị để trace back incident.')
mc(d,36,'A/B routing dùng hash user_id nhằm bảo đảm đặc tính nào?','Cùng một user tiếp tục nhận cùng variant','Mỗi request của cùng user bắt buộc đổi variant','Chỉ user có CTR cao mới vào variant B','Không cần log outcome theo variant','Deterministic assignment bằng hash user_id giữ trải nghiệm nhất quán cho cùng user trong thí nghiệm.')
mc(d,14,'Git nên track gì khi dataset lớn được quản lý bằng DVC?','File .dvc nhỏ chứa hash dữ liệu','Mọi bản sao dataset GB ở mỗi commit','Chỉ file ảnh UI của dataset','Access key của remote data','DVC lưu content-addressable data riêng, Git track pointer .dvc liên kết code/data version.')
mc(d,15,'Credential DVC remote cần cấu hình riêng trên máy thì nên lưu thế nào?','Dùng cấu hình --local và không commit credential','Ghi key cứng vào dvc.yaml công khai','Nhúng key vào tên model registry','Đặt key trong mọi artifact model','Remote best practices dùng --local để giữ credential local, IAM role cho CI/CD và không hardcode key.')
mc(d,16,'dvc repro quyết định stage nào cần chạy lại dựa trên điều gì?','Dependency thay đổi làm stage stale','Chỉ theo thứ tự alphabet của stage','Luôn train lại mọi stage dù không đổi','Chỉ theo tuổi file .gitignore','Smart caching của dvc repro chạy stage stale do deps đổi và bỏ stage chưa thay đổi.')
mc(d,17,'DVC và MLflow bổ sung nhau qua phân công nào?','DVC quản lý pipeline/data version; MLflow metrics/model registry','DVC chỉ ghi latency; MLflow chỉ lưu raw dataset','Cả hai chỉ là web server inference','Cả hai thay thế Git source code hoàn toàn','DVC phục vụ data versioning/pipeline; MLflow track metrics và registry lifecycle.')
mc(d,19,'Điều gì khiến CI/CD cho AI cần eval gate ngoài unit/integration test?','Model có thể thay đổi chất lượng do code hoặc dữ liệu dù pipeline chạy được','Model weights luôn deterministic như binary','Accuracy không thể giảm khi code test pass','Dữ liệu không thuộc pipeline input','AI artifact gồm weights/metadata, có nondeterminism và cần model eval/data validation trên cả code/data changes.')
mc(d,20,'Data validation fail trước training nên dẫn tới hành vi nào?','Dừng sớm để tránh train trên dữ liệu lỗi và tốn GPU','Vẫn train rồi luôn deploy để lấy feedback','Chỉ bỏ ghi log lỗi','Tăng epoch để bù dữ liệu lỗi','Fail fast dừng pipeline khi data validation fail, trước training tốn tiền.')
mc(d,21,'OIDC federation trong CI/CD production thay thế loại credential nào?','AWS key sống lâu được lưu cố định','Model signature input/output','File pointer .dvc','Golden test labels','OIDC giúp dùng identity ngắn hạn theo run thay long-lived AWS keys.')
mc(d,23,'Vì sao eval gate nên dùng fixed held-out test set?','Giữ cơ sở so sánh ổn định giữa model mới và production','Để retrain model trực tiếp trên test sau mỗi gate','Để đổi ngẫu nhiên test mỗi lần và bỏ lịch sử','Để chỉ đo một metric bất kể SLO','Fixed held-out set giúp so sánh baseline nhất quán; nên log nhiều metric và dùng threshold riêng.')
mc(d,26,'Shadow deployment phân biệt với canary ở cách trả response nào?','Model mới xử lý bản sao traffic nhưng response không trả user','Model mới trả 5% response ngay cho user','Luôn thay từng pod và trộn version','Chỉ deploy v2 sau khi xóa v1','Shadow log response v2 và trả v1 cho user; canary cho một tỷ lệ user traffic thực sự dùng v2.')
mc(d,28,'Blue/green giữ v1 sống sau khi switch load balancer nhằm mục tiêu gì?','Rollback nhanh nếu v2 phát sinh vấn đề','Huấn luyện v1 bằng response v2','Gộp hai model weights thành một','Tránh phải chạy smoke/integration test','Giữ môi trường cũ trong khoảng giám sát cho phép instant rollback; đánh đổi là tài nguyên song song.')
mc(d,33,'Bài test chạy tải ổn định trong một giờ để tìm memory leak thuộc loại nào?','Soak test','Spike test tăng tải đột ngột','Unit test tokenizer','Data schema test','Soak test duy trì tải kéo dài để phát hiện memory leak; spike test kiểm phản ứng trước cú tăng tải.')
